import{_ as t,o,c as r,a1 as a}from"./chunks/framework.C5u0ZYB0.js";const p=JSON.parse('{"title":"Privacy policy","description":"","frontmatter":{},"headers":[],"relativePath":"docs/privacy.md","filePath":"docs/privacy.md","lastUpdated":1789986016000}'),i={name:"docs/privacy.md"};function s(n,e,l,c,h,d){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="privacy-policy" tabindex="-1">Privacy policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy policy&quot;">​</a></h1><p>This page describes what Aquilifer, the browser extension, does with your data. It&#39;s written in plain language on purpose; where a claim needs more detail, it links to the relevant feature page rather than repeating it here.</p><h2 id="the-short-version" tabindex="-1">The short version <a class="header-anchor" href="#the-short-version" aria-label="Permalink to &quot;The short version&quot;">​</a></h2><p>Aquilifer doesn&#39;t have a server. There is no Aquilifer-operated backend, database, or analytics endpoint anywhere in this project, so there&#39;s nothing for Aquilifer&#39;s developers to collect, see, or sell, because it&#39;s never sent to them in the first place. Everything Aquilifer stores lives in your browser&#39;s local storage, on your own machine, and the only network requests it ever makes are the ones <em>you</em> configured: directly from your browser to the LLM provider you connected (Anthropic, OpenAI, or a self-hosted endpoint you pointed it at).</p><h2 id="what-aquilifer-stores-and-where" tabindex="-1">What Aquilifer stores, and where <a class="header-anchor" href="#what-aquilifer-stores-and-where" aria-label="Permalink to &quot;What Aquilifer stores, and where&quot;">​</a></h2><p>All of it is in <code>chrome.storage.local</code> — sandboxed storage private to the extension, on your device, in your browser profile. None of it syncs to a Google account or any other cloud service.</p><ul><li><strong>Provider credentials</strong> (API keys, base URLs, model selections you&#39;ve configured). See <a href="/projects/aquilifer/docs/providers">Providers</a>. Plain text by default; optionally encrypted at rest with a password you choose, via <a href="/projects/aquilifer/docs/vault">the vault</a> — see that page for exactly what the vault does and doesn&#39;t cover.</li><li><strong>Connected-site grants</strong>: which sites you&#39;ve approved, and which provider each one is bound to. See <a href="/projects/aquilifer/docs/connecting">Connecting a site</a>.</li><li><strong>Request history</strong>: the prompts and responses for every request a connected site has made, kept as a local audit log. See <a href="/projects/aquilifer/docs/history">History</a>. This is never encrypted, vault or not, and is never sent anywhere or fed back into a future request.</li><li><strong>Your own settings</strong>: rate limits, notification cooldowns, and display preferences (font size, popup width). See <a href="/projects/aquilifer/docs/rate-limiting">Rate limiting</a> and <a href="/projects/aquilifer/docs/appearance">Appearance</a>.</li></ul><h2 id="what-aquilifer-sends-over-the-network-and-to-whom" tabindex="-1">What Aquilifer sends over the network, and to whom <a class="header-anchor" href="#what-aquilifer-sends-over-the-network-and-to-whom" aria-label="Permalink to &quot;What Aquilifer sends over the network, and to whom&quot;">​</a></h2><p>Exactly one kind of outbound request: a completion request to the LLM provider <em>you</em> configured, sent directly from your browser using the credential you provided. If you connected an Anthropic key, requests go to Anthropic&#39;s API; if you pointed Aquilifer at a self-hosted model, requests go there instead. Aquilifer has no server of its own in that path; it doesn&#39;t proxy, log, or forward your requests anywhere else.</p><p>A connected website never receives your credential. It receives only the completion (and, for a provider-specific interface, that provider&#39;s response shape). See <a href="/projects/aquilifer/docs/api">The page-facing API</a> for exactly what a connected site can and can&#39;t do.</p><h2 id="no-analytics-no-tracking" tabindex="-1">No analytics, no tracking <a class="header-anchor" href="#no-analytics-no-tracking" aria-label="Permalink to &quot;No analytics, no tracking&quot;">​</a></h2><p>Aquilifer doesn&#39;t include any analytics, telemetry, crash-reporting, or advertising code. It doesn&#39;t know how many people use it, what they ask their LLM, or which sites they&#39;ve connected, because none of that ever leaves your browser.</p><h2 id="your-control-over-this-data" tabindex="-1">Your control over this data <a class="header-anchor" href="#your-control-over-this-data" aria-label="Permalink to &quot;Your control over this data&quot;">​</a></h2><ul><li><strong>Disconnect a site</strong> at any time (the toolbar popup or Options&#39; Connected Sites tab), which revokes its access immediately.</li><li><strong>Remove a provider</strong>, which deletes its stored credential.</li><li><strong>Clear history</strong> from the History tab.</li><li><strong>Uninstalling the extension</strong> deletes everything Aquilifer stored, the same as uninstalling any browser extension.</li></ul><h2 id="permissions-this-extension-requests" tabindex="-1">Permissions this extension requests <a class="header-anchor" href="#permissions-this-extension-requests" aria-label="Permalink to &quot;Permissions this extension requests&quot;">​</a></h2><ul><li><strong><code>storage</code></strong>: to keep the data described above locally.</li><li><strong><code>activeTab</code></strong>: so the toolbar popup can show the current tab&#39;s connection status; granted only for the tab you clicked the toolbar icon on, never any other tab.</li><li><strong><code>notifications</code></strong>: to show a system notification when a site is rate-limit blocked.</li><li><strong>Host access to every site</strong>: <code>window.aquilifer</code> is injected on every page so any site can offer to use it, the same way a page checks for <code>window.ethereum</code>. This is what lets Aquilifer work on a site without that site needing to be special-cased ahead of time. It does not mean Aquilifer reads page content or browsing activity; the injected script only responds to a page&#39;s own explicit requests to <code>window.aquilifer</code>.</li></ul><h2 id="questions" tabindex="-1">Questions <a class="header-anchor" href="#questions" aria-label="Permalink to &quot;Questions&quot;">​</a></h2><p>Aquilifer is <a href="https://github.com/On0n0k1/aquilifer" target="_blank" rel="noreferrer">open source, Apache 2.0 licensed</a>: the actual behavior described above is verifiable by reading the code, not just taking this page&#39;s word for it. If something here seems wrong or you have a question this page doesn&#39;t answer, <a href="https://github.com/On0n0k1/aquilifer/issues" target="_blank" rel="noreferrer">open an issue</a>.</p>',18)])])}const f=t(i,[["render",s]]);export{p as __pageData,f as default};
